import{_ as o,o as c,c as d,a3 as p}from"./chunks/framework.DdpBa4_E.js";const H=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/technology-career-guide/05-洞悉人事篇：HR是如何在成百上千份简历中挑选候选者的.md","filePath":"books/technology-career-guide/05-洞悉人事篇：HR是如何在成百上千份简历中挑选候选者的.md","lastUpdated":1794316978000}'),l={name:"books/technology-career-guide/05-洞悉人事篇：HR是如何在成百上千份简历中挑选候选者的.md"};function t(a,e,i,r,s,n){return c(),d("div",null,[...e[0]||(e[0]=[p('<p>前面一节聊了面试前如何技术准备，这节来说说求职路上必遇的角色：<code>HR</code>/人事，一次求职面试过程中，通常都会先与这个角色打交道。</p><p>人事这个角色分歧很大，有令人厌烦的尖酸刻薄者，有善于交际的亲和派，也有狐假虎威的二五仔，甚至有啥也不懂的毕业生。</p><p>在很多公司举行的匿名投票中，票选最让人讨厌的职位时，<code>HR</code>往往都是首当其冲的那个。</p><p>相对来说，<code>HR</code>是一个吃力不讨好的职位，需要很高的情商才能做得很好，否则很容易遭人嫌，对外让应聘者讨厌（态度不好），对内让领导嫌弃（招不到人）、让员工厌恶（克扣考勤），所以做好<code>HR</code>其实很难。</p><p>不过这里就不对<code>HR</code>的难处做过多描述了，下面重点谈一谈<code>HR</code>对求职途中的影响。</p><h2 id="一、重新认识一下-hr" tabindex="-1">一、重新认识一下 HR <a class="header-anchor" href="#一、重新认识一下-hr" aria-label="Permalink to &quot;一、重新认识一下 HR&quot;">​</a></h2><p>任何企业中都会有<code>HR（Human Resource）</code>，翻译过来叫人力资源，但也习惯被称为人事。小一些的公司也许只会有<code>1~2</code>个人事专员，具备一定规模的企业则会组建人力资源部/人事部。其工作职责分为六大模块。</p><ul><li>人力资源规划：根据公司业务发展需求，规划内部各部门岗位需求和人员招聘数量。</li><li>执行招聘计划：在各渠道发布招聘信息、负责应聘者的初次筛选、面试接待与<code>HR</code>面等。</li><li>组织内部培训：负责内部岗位技能、企业文化、新人入职等培训，督导培训计划的实施。</li><li>参与绩效管理：参与制定绩效方案、组织绩效实施、评估、反馈等工作，完善绩效体系。</li><li>核对员工考勤：核实员工的打卡、迟到、缺勤、旷工、请假、工牌、卫生等各类考勤情况。</li><li>处理劳动关系：处理入职、试用、转正、升职、请假、异动、劝退、裁员等劳动管理工作。</li></ul><p>当然，并非所有公司的人事都具备处理上述所有工作的权利，小一些的公司也许老板会直接参与其中，或者规模较大的企业还会有行政部辅助，但组织架构完善的企业，基本上都会规划出人力资源部，上述职责将会统统放权给该部门，但这些与我们没有太大关系，重点把注意力放在第二条，这是作为求职者需要关注的。</p><h3 id="那些千年不变的只招不聘岗" tabindex="-1">那些千年不变的只招不聘岗 <a class="header-anchor" href="#那些千年不变的只招不聘岗" aria-label="Permalink to &quot;那些千年不变的只招不聘岗&quot;">​</a></h3><p><code>HR</code>是求职路上的第一关，通常会负责应聘者的简历筛选，但先记住：<strong>有些<code>HR</code>并非真心招聘</strong>。这具体是怎么回事呢？</p><p>想要弄明白这个问题，就不得不先说清<code>HR</code>的绩效机制。<code>KPI</code>绩效考核制度是大部分企业中都存在的，一个员工绩效系数的高低，也将直接影响其工资收入，而人事部门同样涵盖在绩效考核的范围内，一般<code>HR</code>的绩效指标有如下几点。</p><ul><li>成本控制率：对员工的工资、奖金、福利补贴等成本不能超出预算。</li><li>员工离职率：通常是指自己负责招入的新员工，需要控制离职率。</li><li>内部满意度：主要指内部员工是否对人事有不满意、投诉，出现则会影响绩效。</li><li>培训完成率：督办一场培训时，是否顺利完成、员工到场比例、员工满意度等。</li><li>招聘完成率：主要跟面试邀约数量、到公司应聘人数、新员工的入职人数等挂钩。</li><li>……</li></ul><p>这里抛开其他无关的绩效指标不谈，重点看最后一条关于招聘类的绩效指标，其中面试邀约数、实际应聘数、新员工入职人数等都会影响<code>HR</code>的绩效，这一条也是专门负责招聘的<code>HR</code>，在绩效考核制定中，对绩效系数影响最大的一个指标，意味着该指标会直接影响某些公司的<code>HR</code>收入，因此市场上也有不少“非真心”的<code>HR</code>出现。</p><p align="center"><img src="https://p1-juejin.byteimg.com/tos-cn-i-k3u1fbpfcp/aaef555d5cb043489e18c7f0f1d58a73~tplv-k3u1fbpfcp-watermark.image?" alt="阴险" width="50%"></p><p>当你投递简历后，被对方邀请过去面试时，可能你只是她刷<code>KPI</code>的工具，对方发布这个招聘需求属于“只招不聘”，你的作用在于帮她完成当月的绩效指标，为什么有些<code>HR</code>会这么干呢？</p><p>其实经过前面的绩效分析后，相信大家不用我说也就明白了，也就是为了把自己的招聘完成率提高，拉高自己的绩效系数罢了。</p><blockquote><p>PS：对于这点大家简单了解即可，虽然市场上有这类情况，但毕竟与整体情况对比，那也只是少数，所以不必太过在意，心里有谱就行。更多的招聘需求还是真心为了招人，而并非<code>HR</code>刷绩效的手段。</p></blockquote><h3 id="为什么大部分-hr-会比较热情" tabindex="-1">为什么大部分 HR 会比较热情？ <a class="header-anchor" href="#为什么大部分-hr-会比较热情" aria-label="Permalink to &quot;为什么大部分 HR 会比较热情？&quot;">​</a></h3><p>相信大家见到的很多<code>HR</code>，在接待你时都比较热情，这是为什么呢？</p><p>一方面是出于礼貌和职业素养，而另一方面则有关她的利益，除开能够帮她提高绩效系数外，同时还有一些额外的好处。以我一位做<code>HR</code>的朋友为例，曾经我与其聊天时，她叫我有机会给他介绍没工作的人过去上班，我问过她是因为什么原因呢，她的回答大体如下：</p><blockquote><p>因为有人过去面试可以帮她刷绩效，同时假设入职了，她有一定的奖金（这笔奖金不多），如果后续入职员工比较稳定，在厂里转正之后，又会得到一笔不小的奖金。</p></blockquote><p>听了上述回答后，相信大家应该能够想明白下面这三个问题。</p><ul><li>你的面试能给 HR 带来什么？</li><li>你的入职能给 HR 带来什么？</li><li>你的转正能给 HR 带来什么？</li></ul><p>但她当时是在工厂做<code>HR</code>，负责工厂的招工。对于<code>IT</code>公司的<code>HR</code>来说，可能细节上会有所不同，但你的面试、入职、转正，多多少少都会给她带来一些好处或奖励。</p><blockquote><p><em>PS（玩笑话）：如果后续有进厂想法的待职人员，请立刻、马上联系我！我可以帮你拖关系进个厂～</em></p></blockquote><p>OK，对于<code>HR</code>招聘的那些事就此打住，大家只要稍微对这些有了解就好了，毕竟只是为了让你更熟悉<code>HR</code>，更重要的是接下来的内容：技术行业的<code>HR</code>是如何筛选简历的呢？</p><h2 id="二、技术行业的-hr-是如何筛选简历的" tabindex="-1">二、技术行业的 HR 是如何筛选简历的？ <a class="header-anchor" href="#二、技术行业的-hr-是如何筛选简历的" aria-label="Permalink to &quot;二、技术行业的 HR 是如何筛选简历的？&quot;">​</a></h2><p>想要了解技术行业的<code>HR</code>是如何筛选简历的，那得先明白一个道理：<strong>九成八以上的人事并不懂技术</strong>，但你投递简历后第一步就是人事做筛选。不知是否有人存在这种经历：</p><ul><li>明明我简历上技术写得很牛逼，项目写得也很优秀，但为啥一投简历就没反应啊？</li></ul><p>如果你有这个困扰，那很有可能是因为你的简历太丑了，或者太过花哨了，这容易遭到<code>HR</code>的排斥。毕竟她也不懂技术啊，当她打开你的简历之后，映入眼帘的就是排版不公正、样式特别丑、模板花里胡哨……问题时，可能她就是啪地一下，很快啊，就把简历关了，然后拖进回收站，整套动作一气呵成。</p><p>所以，牢记一点，你想要简历的通过率高一点，第一步应该至少保证足够整洁，不说要让人家眼前一亮，但至少别给人家留下负面印象，因为一个岗位往往有很多人投简历，多你一个不多，少你一个也不少，简历如果很丑的话，的确会影响简历通过率。</p><h3 id="hr-筛选简历的流程" tabindex="-1">HR 筛选简历的流程 <a class="header-anchor" href="#hr-筛选简历的流程" aria-label="Permalink to &quot;HR 筛选简历的流程&quot;">​</a></h3><p>明白<code>HR</code>并不懂技术这个前提后，接着来聊聊<code>HR</code>筛选简历的流程，以及<code>HR</code>在不懂技术的情况下，她是如何筛选简历的、关注点又会放在哪儿。</p><p>先来说说筛选流程：</p><blockquote><p>美好的一天，元气满满的<code>HR</code>坐到了电脑桌前，接着打开了招聘平台，结果一看，好家伙，未读消息<code>99+</code>，这么多可怎么办？随机抽取一半直接<code>pass</code>掉，直接让工作效率提升<code>50%</code>。</p></blockquote><p>哈哈哈，上面是开个玩笑，下面正式说说筛选流程。</p><ul><li>美好的一天，元气满满的<code>HR</code>坐到电脑桌前，打开了招聘平台……</li><li>随机点开一份投递的简历，简单看两眼快速扫描简历的整体信息。</li><li>如果简历整体信息满足需求，再花费<code>8~15</code>秒搜索简历中的关键指标。</li><li>浏览简历搜索到关键信息后，接着会对简历进行评估，合适的单独拎出来。</li><li>对于评估合格的简历，<code>HR</code>会花费<code>1~3</code>分钟仔细阅读，重点关注是否与招聘需求匹配。</li><li>简历经过仔细审阅后，各项条件都符合招聘需求，接着联系应聘者，发出面试邀约。</li></ul><p>上述这个过程是“人肉式简历筛选”的过程，也是中小型企业会采用的方式。但国内一些大厂除外，它们往往具备完善的人力资源系统，内部会有招聘流程模块。</p><p>大厂的大致简历筛选流程如下。</p><ul><li>简历首先被录入系统（从招聘渠道对接），简历会进入初审状态。</li><li>然后交给系统<code>AI</code>进行筛选，<code>AI</code>会快速过滤掉一批不合适的简历。</li><li>接着会从简历中快速提取关键指标、词汇，生成应聘者的个人画像（报表/图像）。</li><li>通过求职者的个人画像比对投递的岗位<code>JD</code>，判断求职者是否适合这个岗位。</li><li>匹配岗位<code>JD</code>的求职者，才会真正由系统交给<code>HR</code>进行最终评估，合适则会锁住简历。</li><li>……</li></ul><p>对比前面“纯手工”筛选简历的方式，大厂这种使用程序介入处理的方式更为智能，尤其是应对大厂每天接到的海量简历，这种系统能极大程度上减轻<code>HR</code>的工作量。</p><p>而且要注意一点，大厂为了防止每天出现海量的重复简历，通常这类系统对简历都有冷却期，也就是当你的简历被<code>pass</code>过一次之后，需要等待一段时间后才能继续投递。在冷却期间内，就算多次反复投递也无法生效，系统在最开始就会自动过滤掉冷却期内的简历。</p><h3 id="hr-在筛选简历时的关注点" tabindex="-1">HR 在筛选简历时的关注点 <a class="header-anchor" href="#hr-在筛选简历时的关注点" aria-label="Permalink to &quot;HR 在筛选简历时的关注点&quot;">​</a></h3><p>前面简单了解简历筛选的流程后，下面说说<code>HR</code>在筛选简历时的关注点，这将直接影响到简历的通过率。只有当大家真正明白了<code>HR</code>的关注点之后，才能写出一份比较不错的简历，但本章不会过多阐述简历优化的内容，这些东西都是后话，本章旨在<strong>洞悉人事</strong>。</p><p><img src="https://p3-juejin.byteimg.com/tos-cn-i-k3u1fbpfcp/f717df8e33614b73be0f7438fb438064~tplv-k3u1fbpfcp-watermark.image?" alt="简历筛选" loading="lazy"></p><p><code>HR</code>在上述不同的环节中，对简历信息的关注是不同的，如果你简历在任一环节有问题，都有可能影响简历的通过率。</p><p>先来聊聊<code>HR</code>刚打开简历的第一眼会关注什么呢。简历整洁性、应聘者的基本信息，如果简历上的字七扭八歪或者比较“辣眼睛”，这是很有可能被淘汰的，毕竟<code>HR</code>大多数是女性，女性通常喜美厌丑，简历的美观整洁程度确实会成为筛选的第一原则。</p><p>不过正常套用简历模板的情况下，基本不会由于外观被<code>pass</code>，所以下面就来聊聊<code>HR</code>会关注哪些基本信息。学历、年龄、工作年限，看这些信息是因为能够通过这些信息做最快筛选，学历、工作年限不合格者会直接<code>pass</code>，同时看年龄是为了核实简历真实性，可以根据年龄来简单推断学历、工作年限是否真实。</p><p>通过前面的快速筛选阶段后，接着<code>HR</code>会对满足条件的简历进行快速过滤，这时的关注点会在期望薪资、上家公司信息与业务、以及历史工作履历上，第一点就不必我多说了，从这点能精准地得知是否能开起你想要的工资，如果给不到你想要的期望薪资，也会直接<code>pass</code>。</p><blockquote><p>正是由于这点原因，所以很多人会在简历写上“薪资面议”，要不要写面议呢？简历优化篇再细聊。</p></blockquote><p>除开期望薪资外，还会去瞅你的工作经历，主要是看你任职的上家公司，在此期间，会关注上家规模、你的岗位以及公司业务性质，这三点会决定你与公司的匹配度。</p><p>如果你上家公司是<code>500</code>强、国内/外大厂，这无疑是你很大的加分项。</p><p>看了你上家公司的规模后，接着会看一下你在上家公司的岗位，是否与目前招聘的岗位匹配，对于匹配度高的应聘者会优先选择，比如招项目经理，你有过项目经理的履历，无疑你会更合适一些。</p><p>最后，<code>HR</code>还会分析你的上家，与目前公司的业务匹配度，如果是同一业务类型的项目，这绝对将成为大大滴加分项。比如：</p><blockquote><p>一个做金融性质的企业招聘，那最希望的是：招到一个之前具有金融经验的人。毕竟有经验代表上手速度快，如果招了一个之前专门写管理系统的新人进来，先不论技术如何，就光金融领域内的一堆业务概念，理解起来也需要不短的时间。</p></blockquote><p>分析完你上家公司的情况后，接着会看看你的工作生涯，也就是你历史从业经历。如果你频繁地在不同公司内横跳，这无疑是会被<code>pass</code>的类型。例如你在每家公司待的平均工龄是一年，那<code>HR</code>心里会想：“我假设把你招进来了，一年之后你业务熟了，活干得也越来越快了，是不是很有几率也会跑路呢？”</p><p>企业用人的第一原则是追求稳定，谁都不希望自己的企业内招到一个不稳定的人，所以具备“不稳定因素”的应聘者会直接在简历筛选中<code>pass</code>。</p><p>经过上述两轮筛选后，<code>HR</code>手中留下的简历，既满足公司招聘的硬性条件，同时又贴合公司的业务线、岗位需求，所以接下来<code>HR</code>会做最终的评选阶段，也就是看应聘者的“个人技术栈与项目经历”。诸多小伙伴看到这里就疑惑了：你前面不是说<code>HR</code>不懂技术吗？！？？为啥<code>HR</code>会去看个人技术栈啊？</p><p>想要弄懂此问题，就得先知道：<strong><code>HR</code>发布的招聘需求怎么来的</strong>？无非就两个方式。</p><p><strong>来源一：用人部门写的</strong>。需要招聘一个什么能力的人，最清楚的莫过于用人部门本身。当部门缺人时，尤其存在技术岗位空缺时，<code>HR</code>并不清楚要招一个什么技术的人进来啊，所以大部分公司会由用人部门本身去写招聘需求，然后交给<code>HR</code>对外发布。</p><p><strong>来源二：用人部门给的关键字去复制同行的</strong>。不是所有公司的技术部门，都会亲自给<code>HR</code>写招聘需求，毕竟大部分“技术人”的文笔水平欠佳，你叫我形容一下招什么人可以，但叫我写出标准的招聘需求就有些为难，通常这种情况下，用人部门只会给出一些技术栈关键字。但<code>HR</code>看不懂这些技术栈啊，为此就直接去参考同行的招聘，将对应的招聘关键字套入其中，从而形成了自己的招聘需求。</p><p>但无论<code>HR</code>是通过哪种方式弄到的招聘需求，但最终手里都会有一份技术关键字的清单，虽然<code>HR</code>不能直接筛选出技术达标的简历，但起码也能大概淘汰一些技术不达标的简历。</p><p>所以，在最后这个筛选阶段中，<code>HR</code>会通过用人部门给出的关键字，对简历进行精准匹配，尽量把简历的精准度提高（最后这个详细评审阶段中，有些专业的<code>HR</code>会详细阅读你的简历，从而判断你与当前岗位到底合不合适）。</p><h3 id="hr-也许不是最终决断者" tabindex="-1">HR 也许不是最终决断者 <a class="header-anchor" href="#hr-也许不是最终决断者" aria-label="Permalink to &quot;HR 也许不是最终决断者&quot;">​</a></h3><p>经过前面<code>HR</code>的一系列筛选后，你的简历经过千辛万苦，终于通过了重重难关，此时屏幕对面的你，也许会歪嘴一笑：“嘿，就你这小小<code>HR</code>，能难住我？”</p><p>但此刻别高兴得太早，因为<code>HR</code>只是你简历的第一关，我们都懂<code>HR</code>不会技术这个道理，相信招聘的公司也不会不懂，所以当<code>HR</code>筛选出一批相对满意的简历后，接着会递给懂技术的用人部门！</p><p>纳尼？技术面试官这时就出场了？<code>Yes</code>，越专业、规模越大的企业招聘，技术面试官参与简历筛选的几率也就越大。身为求职方的我们，不想去参加一场无意义的面试，而作为招聘方的企业同样如此，与其喊很多人过来面试，不如从中再挑选出一批优秀者发出邀约，这样也能极大程度上减少多场不必要的面试。</p><blockquote><p>既然技术面试官会参与简历筛选，而同为技术人的他，在看简历时会关注什么呢？</p></blockquote><p>现在幻想你是一位面试官，现在手里有份简历，你站在技术人的角度出发，首先会关注什么？</p><p>毫无疑问，必然是关注对方的技术，当<code>HR</code>给坐在工位上的你，递来一份简历时，场景如下：</p><ul><li>（用漫不经心的目光一瞥，稍后嘴角上扬邪魅一笑）：嘿，让我看看这小子技术怎么样！</li></ul><p>技术面试官在看简历时，并不会去关注你年龄多大、学历多高，更看重的是你的技术能力，也正因他与你同为技术人，所以对技术的考查会更加专业，看简历时大多数抱着这三个想法。</p><ul><li>①先看看找工作的这小子，他会的我会不会，懂得有没有我多～</li><li>②这小子会得不少，再看看他懂得有多深！</li><li>③这小子技术不错，让我看看他做过什么项目，有没有我手上的项目牛～</li></ul><p>综上，技术面试官在筛选简历时，通常会看技术广度、深度，以及项目经验这三点，所以想要通过技术面试官的简历筛选，这三点上面要下功夫，既不能太装，也不能显得太弱，毕竟太装了容易面试遭到惨打，太弱了入不了对方法眼。</p><blockquote><p>这三点具体该如何写，也会在后面《简历优化篇》中详细阐述，这篇只了解大概的简历筛选流程。</p></blockquote><p>最后记住一点：<strong>简历是第一关，也是最重要的一关</strong>！当技术面试官看完你的简历后，通知人事给你发起面试邀约，这意味着你的简历至少得到了他的认可，你要做的就是在面试中发挥出简历上的水平，薪资能在对方接受的范围之内时，你拿到<code>Offer</code>的几率八九就不离十了（除开有比你更合适的人选，或你的性格、价值观不合适外）。</p><h2 id="三、公司招聘时的意中人是怎样的" tabindex="-1">三、公司招聘时的意中人是怎样的？ <a class="header-anchor" href="#三、公司招聘时的意中人是怎样的" aria-label="Permalink to &quot;三、公司招聘时的意中人是怎样的？&quot;">​</a></h2><p>截至目前，大家认真阅读完前面的内容之后，相信对<code>HR</code>、技术面试官如何筛选简历的流程，已经熟透于心了。最后这个阶段，来聊聊企业招聘时，到底想招到什么样的人。</p><p>众所周知的一点，现如今找工作越来越难，当准备开启一场面试之旅时，从自信到自闭的人不在少数，似乎现在找工作变得很困难了，是不？你这么想，实则企业也是这样想的，<code>HR</code>也是这么想的。</p><p align="center"><img src="https://p3-juejin.byteimg.com/tos-cn-i-k3u1fbpfcp/0dbf8a742420490ebf64d8b504bbaab3~tplv-k3u1fbpfcp-watermark.image?" alt="求职vs招聘" width="50%"></p><p>此时你小小的脑袋应该有着大大的疑惑：“找工作的人这么多，为什么企业招人还难啊？”</p><p>其实更为具体一点来说，是企业想招到一个满意的人难，如今市场的技术人才鱼龙混杂，会吹技术差的、技术强不会吹的、没经验硬包装的、技术好又会吹但脾气差的……各色各样的求职者比比皆是，这就导致了企业想要招到“意中人”的难度大大提升，那企业眼中的“意中人”长啥样呢？</p><ul><li>身披黄金甲，脚踏七彩云……</li></ul><p>呸，走错片场了，通常企业招聘时真正的意中人要求如下。</p><ul><li>①<strong>能干活</strong>：掌握的技术能力可以满足公司业务的基本需求。</li><li>②<strong>上手快</strong>：做过与公司业务接近的项目，熟悉公司所用的技术栈，要花费的培养成本低。</li><li>③<strong>够稳定</strong>：入职后能够持续给公司贡献价值，不会入职一段时间后就提桶跑路。</li><li>④<strong>高性价比</strong>：除开能完全与空缺岗位相匹配外，能干活的前提下还“不贵”。</li><li>⑤<strong>潜力高</strong>：具备不错的学习能力，能随着公司业务的不断发展持续成长。</li></ul><p><strong><code>活好价廉够稳定</code></strong>，这是企业眼中的意中人，是不是与大家求职时的“<strong>钱多事少离家近</strong>”很像？理想很丰满，现实却很骨感，求职往往很难找到一份“<strong>钱多事少离家近</strong>”的工作，最终结局大多以“<strong>凑合着干</strong>”结尾，而企业招聘时亦是如此，最终也只能满足于“<strong>又不是不能用</strong>”这个水准。</p><p>我们聊这个话题有何意义呢？很简单，我们要做的就是：<strong>把自己变成别人喜欢的样子</strong>。企业招聘想要上手快的，我们投简历时，就可以专门去找和上家公司业务接近的岗位。企业想要高性价比的，那就执行之前聊到的降维打击方案……总之，尽量去迎合企业的用人需求，呈现给企业一种 <strong>“我是最合适”</strong> 的感觉即可。</p><h2 id="四、总结" tabindex="-1">四、总结 <a class="header-anchor" href="#四、总结" aria-label="Permalink to &quot;四、总结&quot;">​</a></h2><p>又一个篇章进入了尾声，这章聊的内容比较特殊，更多的是在帮大家熟悉对手，详细拆解了<code>HR</code>的工作职责与绩效组成、招聘中的一些坑、<code>HR</code>筛选简历的流程，以及技术面试官筛选简历的关注点等内容。虽然看起来不具备太多营养，但这是《简历优化篇》之前，不得不先讲明的一些东西，毕竟有句话叫：知己知彼，才能百战不殆。</p><p>简历优化这玩意儿，网上流传着诸多资料，但很多资料中仅是只言片语，或者干脆只是个噱头来引流，从没有一份真正能帮助大家做好简历优化的资料出现，而下章的内容就会对其进行全面阐述，详细讲到简历优化的各种情况啦！</p><p>最后也对本章的简历筛选流程做个简单总结，不多废话了，上个图就一清二楚，如下：</p><p align="center"><img src="https://p6-juejin.byteimg.com/tos-cn-i-k3u1fbpfcp/6ad84249e0b14bf6917c2376d320ee3e~tplv-k3u1fbpfcp-watermark.image?" alt="筛选流程"></p><p>其实这些内容，原本是规划在《简历优化篇》里简单叙述的，但后面转念一想，想要彻底做好简历优化，这些流程中的细节就不得不明白，因为如果不清楚这些细节，就很难真正理解简历的一些东西：为什么要做优化？为什么要那样写？</p><p>所以，与其授人以鱼，不如授之以渔，大家搞懂简历筛选的内幕之后，如何做简历优化心里自然多少有点数了，再结合后续《简历优化篇》的熏陶，大家就可以彻底掌握简历优化的技巧。那么，我们下节再见啦～</p>',95)])])}const u=o(l,[["render",t]]);export{H as __pageData,u as default};
